<script setup>
import { computed, onMounted, reactive, ref } from 'vue'

const props = defineProps({
  api: { type: Function, required: true },
  assets: { type: Array, default: () => [] },
  isAdmin: { type: Boolean, default: false }
})

const center = ref({ components: [], incidents: [] })
const loading = ref(false)
const saving = ref(false)
const error = ref('')
const notice = ref('')
const showComponentModal = ref(false)
const showIncidentModal = ref(false)
const showUpdateModal = ref(false)
const editingComponent = ref(null)
const selectedIncident = ref(null)
const componentForm = reactive({ slug: '', name: '', description: '', assetId: '', status: 'OPERATIONAL', statusMessage: '', displayOrder: 100, enabled: true })
const incidentForm = reactive({ title: '', summary: '', impact: 'MAJOR', componentIds: [], sourceIncidentId: '' })
const updateForm = reactive({ status: 'IDENTIFIED', message: '' })

const componentStatuses = { OPERATIONAL: '运行正常', DEGRADED: '性能下降', PARTIAL_OUTAGE: '部分不可用', MAJOR_OUTAGE: '重大故障', MAINTENANCE: '维护中' }
const incidentStatuses = { INVESTIGATING: '调查中', IDENTIFIED: '已定位', MONITORING: '持续观察', RESOLVED: '已解决' }
const impacts = { MINOR: '轻微影响', MAJOR: '较大影响', CRITICAL: '严重影响' }
const components = computed(() => center.value.components || [])
const incidents = computed(() => center.value.incidents || [])
const publishedCount = computed(() => incidents.value.filter(item => item.incident?.published).length)
const activePublishedCount = computed(() => incidents.value.filter(item => item.incident?.published && item.incident.status !== 'RESOLVED').length)

function formatDate(value) { return value ? new Date(value).toLocaleString('zh-CN', { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }) : '-' }
function componentStatusLabel(value) { return componentStatuses[value] || value || '-' }
function incidentStatusLabel(value) { return incidentStatuses[value] || value || '-' }
function componentStatusClass(value) { return 'state-' + String(value || '').toLowerCase() }
function toast(message) { notice.value = message; window.setTimeout(() => { notice.value = '' }, 2800) }
function assetName(id) { const asset = props.assets.find(item => String(item.id) === String(id)); return asset ? asset.assetNo + ' · ' + asset.name : '未关联 CMDB 资产' }

async function load() {
  loading.value = true; error.value = ''
  try { center.value = await props.api('/api/v1/status-center') } catch (err) { error.value = err.message || '加载服务状态中心失败' } finally { loading.value = false }
}
function openComponent(component = null) {
  if (!props.isAdmin) return
  editingComponent.value = component
  Object.assign(componentForm, component ? { slug: component.slug, name: component.name, description: component.description || '', assetId: component.assetId || '', status: component.status || 'OPERATIONAL', statusMessage: component.statusMessage || '', displayOrder: component.displayOrder ?? 100, enabled: component.enabled !== false } : { slug: '', name: '', description: '', assetId: '', status: 'OPERATIONAL', statusMessage: '', displayOrder: components.value.length * 10 + 100, enabled: true })
  showComponentModal.value = true
}
async function saveComponent() {
  saving.value = true; error.value = ''
  try {
    const payload = { ...componentForm, assetId: componentForm.assetId ? Number(componentForm.assetId) : null }
    await props.api(editingComponent.value ? '/api/v1/status-center/components/' + editingComponent.value.id : '/api/v1/status-center/components', { method: editingComponent.value ? 'PUT' : 'POST', body: JSON.stringify(payload) })
    showComponentModal.value = false; toast(editingComponent.value ? '服务组件已更新' : '服务组件已创建'); await load()
  } catch (err) { error.value = err.message || '保存服务组件失败' } finally { saving.value = false }
}
function openIncident() {
  Object.assign(incidentForm, { title: '', summary: '', impact: 'MAJOR', componentIds: components.value.filter(item => item.enabled !== false).slice(0, 1).map(item => item.id), sourceIncidentId: '' })
  showIncidentModal.value = true
}
async function saveIncident() {
  saving.value = true; error.value = ''
  try {
    await props.api('/api/v1/status-center/incidents', { method: 'POST', body: JSON.stringify({ ...incidentForm, componentIds: incidentForm.componentIds.map(Number), sourceIncidentId: incidentForm.sourceIncidentId ? Number(incidentForm.sourceIncidentId) : null }) })
    showIncidentModal.value = false; toast('已创建公告草稿，尚未公开'); await load()
  } catch (err) { error.value = err.message || '创建公告草稿失败' } finally { saving.value = false }
}
function openUpdate(detail) {
  selectedIncident.value = detail
  Object.assign(updateForm, { status: detail.incident.status === 'INVESTIGATING' ? 'IDENTIFIED' : detail.incident.status === 'IDENTIFIED' ? 'MONITORING' : 'RESOLVED', message: '' })
  showUpdateModal.value = true
}
async function postUpdate() {
  saving.value = true; error.value = ''
  try { await props.api('/api/v1/status-center/incidents/' + selectedIncident.value.incident.id + '/updates', { method: 'POST', body: JSON.stringify(updateForm) }); showUpdateModal.value = false; toast(updateForm.status === 'RESOLVED' ? '已记录恢复公告' : '公开进展已记录'); await load() } catch (err) { error.value = err.message || '更新公告失败' } finally { saving.value = false }
}
async function publish(detail, enabled) {
  if (!props.isAdmin) return
  saving.value = true; error.value = ''
  try { await props.api('/api/v1/status-center/incidents/' + detail.incident.id + '/' + (enabled ? 'publish' : 'unpublish'), { method: 'POST' }); toast(enabled ? '公告已公开发布' : '公告已从公开状态页撤回'); await load() } catch (err) { error.value = err.message || '更新发布状态失败' } finally { saving.value = false }
}

onMounted(load)
</script>

<template>
  <section class="status-center-view">
    <div class="status-center-top">
      <div><p class="eyebrow">CUSTOMER COMMUNICATION</p><h2>服务状态中心</h2><p>把经过审核的服务信息发布到公开状态页；内部告警和事故不会自动公开。</p></div>
      <div class="status-actions"><a href="/status" target="_blank" class="secondary-button">↗ 预览公开状态页</a><button class="primary-button" :disabled="!components.length" @click="openIncident">＋ 新建服务公告</button></div>
    </div>
    <p v-if="error" class="status-error">{{ error }} <button @click="error = ''">×</button></p><p v-if="notice" class="status-notice">✓ {{ notice }}</p>

    <div class="status-metrics"><article><span>公开组件</span><strong>{{ components.filter(item => item.enabled !== false).length }}</strong><small>已显示于状态页</small></article><article><span>公开公告</span><strong>{{ publishedCount }}</strong><small>审核后可见</small></article><article :class="{ attention: activePublishedCount }"><span>处理中公告</span><strong>{{ activePublishedCount }}</strong><small>已发布且未恢复</small></article><article><span>安全边界</span><strong>人工</strong><small>不自动外泄内部事故</small></article></div>

    <section class="status-grid">
      <article class="status-card component-card"><div class="status-card-head"><div><p>PUBLIC COMPONENTS</p><h3>服务组件</h3></div><button v-if="isAdmin" class="row-action" @click="openComponent()">＋ 配置组件</button></div><p class="card-description">组件可关联 CMDB 用于内部追溯，但公开页仅展示管理员填写的名称、说明与状态。</p><div v-if="loading" class="status-empty">正在同步组件…</div><div v-else-if="!components.length" class="status-empty">还没有服务组件。管理员可以从“配置组件”创建第一个公开服务。</div><div v-else class="internal-component-list"><article v-for="component in components" :key="component.id" :class="['internal-component', { disabled: component.enabled === false }]"><div><div class="component-name-line"><strong>{{ component.name }}</strong><code>{{ component.slug }}</code></div><small>{{ component.description || '暂无公开说明' }}</small><small>{{ assetName(component.assetId) }} · 排序 {{ component.displayOrder }}</small></div><div class="component-actions"><span :class="['internal-state', componentStatusClass(component.status)]">{{ componentStatusLabel(component.status) }}</span><button v-if="isAdmin" class="row-action" @click="openComponent(component)">编辑</button></div></article></div>
    </article>

      <article class="status-card policy-card"><div class="status-card-head"><div><p>PUBLICATION POLICY</p><h3>对外发布守则</h3></div><span class="policy-lock">● 受控</span></div><ol><li><b>先建草稿</b><span>客服可起草公开摘要并选择受影响组件。</span></li><li><b>再由管理员发布</b><span>发布后才会改变公开组件状态与对外可见性。</span></li><li><b>持续追加进展</b><span>调查、定位、观察与恢复形成可追溯时间线。</span></li></ol><div class="policy-note">关联内部事故只用于内部追溯。标题、摘要和更新均需单独编写，不会复制内部内容。</div></article>
    </section>

    <section class="status-card announcement-card"><div class="status-card-head"><div><p>ANNOUNCEMENT QUEUE</p><h3>服务公告队列</h3></div><span>{{ incidents.length }} 条 · 最近 100 条</span></div><div v-if="loading" class="status-empty">正在同步公告…</div><div v-else-if="!incidents.length" class="status-empty">当前没有服务公告。先创建一条草稿，审核后再发布。</div><div v-else class="announcement-list"><article v-for="detail in incidents" :key="detail.incident.id" :class="['announcement-item', { published: detail.incident.published }]"><div class="announcement-main"><div class="announcement-meta"><code>{{ detail.incident.publicNo }}</code><span :class="['announcement-status', 'announcement-' + detail.incident.status.toLowerCase()]">{{ incidentStatusLabel(detail.incident.status) }}</span><span class="impact">{{ impacts[detail.incident.impact] }}</span><span v-if="detail.incident.published" class="published-mark">已公开</span><span v-else class="draft-mark">草稿</span></div><h4>{{ detail.incident.title }}</h4><p>{{ detail.incident.summary }}</p><div class="announcement-components"><span v-for="component in detail.components" :key="component.id">{{ component.name }}</span></div><div v-if="detail.updates?.length" class="last-update"><b>最近进展 · {{ incidentStatusLabel(detail.updates[detail.updates.length - 1].status) }}</b>{{ detail.updates[detail.updates.length - 1].message }}<time>{{ formatDate(detail.updates[detail.updates.length - 1].createdAt) }}</time></div></div><div class="announcement-actions"><small>更新 {{ formatDate(detail.incident.updatedAt) }}</small><button v-if="detail.incident.status !== 'RESOLVED'" class="row-action" :disabled="saving" @click="openUpdate(detail)">记录进展</button><button v-if="isAdmin && !detail.incident.published" class="primary-mini" :disabled="saving" @click="publish(detail, true)">发布到状态页</button><button v-if="isAdmin && detail.incident.published" class="row-action danger" :disabled="saving" @click="publish(detail, false)">撤回公开</button></div></article></div>
    </section>

    <div v-if="showComponentModal" class="status-modal-backdrop" @click.self="showComponentModal = false"><form class="status-modal" @submit.prevent="saveComponent"><header><div><p>PUBLIC COMPONENT</p><h2>{{ editingComponent ? '编辑服务组件' : '配置服务组件' }}</h2></div><button type="button" @click="showComponentModal = false">×</button></header><div class="status-form-grid"><label>公开标识<input v-model="componentForm.slug" required maxlength="80" placeholder="例如 order-api" /></label><label>显示顺序<input v-model.number="componentForm.displayOrder" type="number" min="0" max="9999" /></label></div><label>组件名称<input v-model="componentForm.name" required maxlength="120" placeholder="例如 订单服务" /></label><label>公开说明<textarea v-model="componentForm.description" maxlength="1000" rows="3" placeholder="仅填写可以面向用户公开的服务说明"></textarea></label><label>关联 CMDB 资产（内部追溯用）<select v-model="componentForm.assetId"><option value="">不关联</option><option v-for="asset in assets" :key="asset.id" :value="asset.id">{{ asset.assetNo }} · {{ asset.name }}</option></select></label><div class="status-form-grid"><label>当前公开状态<select v-model="componentForm.status"><option v-for="(label, value) in componentStatuses" :key="value" :value="value">{{ label }}</option></select></label><label>是否在公开页显示<select v-model="componentForm.enabled"><option :value="true">显示</option><option :value="false">隐藏</option></select></label></div><label>状态补充说明<textarea v-model="componentForm.statusMessage" maxlength="300" rows="2" placeholder="例如：已完成维护，服务恢复正常"></textarea></label><footer><button type="button" class="secondary-button" @click="showComponentModal = false">取消</button><button class="primary-button" :disabled="saving">{{ saving ? '保存中…' : '保存组件' }}</button></footer></form></div>

    <div v-if="showIncidentModal" class="status-modal-backdrop" @click.self="showIncidentModal = false"><form class="status-modal incident-modal" @submit.prevent="saveIncident"><header><div><p>PUBLIC ANNOUNCEMENT DRAFT</p><h2>新建服务公告草稿</h2></div><button type="button" @click="showIncidentModal = false">×</button></header><p class="modal-warning">公告创建后仍为草稿，只有管理员点击发布才会对外可见或影响公开组件状态。</p><label>公开标题<input v-model="incidentForm.title" required maxlength="160" placeholder="例如：订单服务响应缓慢" /></label><label>公开摘要<textarea v-model="incidentForm.summary" required maxlength="2000" rows="4" placeholder="描述面向用户可公开的影响范围与当前处理情况；不要粘贴内部日志、账号或排障细节。"></textarea></label><div class="status-form-grid"><label>影响等级<select v-model="incidentForm.impact"><option v-for="(label, value) in impacts" :key="value" :value="value">{{ label }}</option></select></label><label>关联内部事故 ID（可选）<input v-model="incidentForm.sourceIncidentId" type="number" min="1" placeholder="仅用于内部追溯" /></label></div><fieldset><legend>受影响服务组件（至少选一项）</legend><label v-for="component in components.filter(item => item.enabled !== false)" :key="component.id" class="component-check"><input v-model="incidentForm.componentIds" type="checkbox" :value="component.id" /><span><strong>{{ component.name }}</strong><small>{{ componentStatusLabel(component.status) }}</small></span></label></fieldset><footer><button type="button" class="secondary-button" @click="showIncidentModal = false">取消</button><button class="primary-button" :disabled="saving || !incidentForm.componentIds.length">{{ saving ? '创建中…' : '创建草稿' }}</button></footer></form></div>

    <div v-if="showUpdateModal" class="status-modal-backdrop" @click.self="showUpdateModal = false"><form class="status-modal" @submit.prevent="postUpdate"><header><div><p>STATUS UPDATE</p><h2>记录公开进展</h2><small>{{ selectedIncident?.incident.publicNo }} · {{ selectedIncident?.incident.title }}</small></div><button type="button" @click="showUpdateModal = false">×</button></header><label>公告状态<select v-model="updateForm.status"><option v-for="(label, value) in incidentStatuses" :key="value" :value="value" :disabled="value === 'INVESTIGATING'">{{ label }}</option></select></label><label>公开进展<textarea v-model="updateForm.message" required maxlength="1000" rows="5" placeholder="例如：已确认影响范围，团队正在逐步恢复服务。"></textarea></label><p class="modal-warning">若设为“已解决”，已公开公告会将关联组件恢复为正常状态；请确认服务已经恢复。</p><footer><button type="button" class="secondary-button" @click="showUpdateModal = false">取消</button><button class="primary-button" :disabled="saving">{{ saving ? '保存中…' : '发布进展' }}</button></footer></form></div>
  </section>
</template>

<style scoped>
.status-center-view { padding: 30px 34px 48px; color: #1d2b40; }.status-center-top { display: flex; justify-content: space-between; gap: 30px; align-items: flex-end; margin-bottom: 24px; }.status-center-top h2 { margin: 5px 0 7px; font-size: 25px; letter-spacing: -.04em; }.status-center-top > div > p:last-child { color: #78869b; margin: 0; font-size: 13px; }.eyebrow, .status-card-head p, .status-modal header p { margin: 0; font-weight: 800; font-size: 10px; letter-spacing: .12em; color: #6b7b92; }.status-actions { display: flex; align-items: center; gap: 10px; }.primary-button, .secondary-button { border-radius: 8px; padding: 9px 13px; font-weight: 700; font-size: 13px; cursor: pointer; text-decoration: none; }.primary-button { border: 1px solid #1e4d80; background: #215b92; color: white; }.primary-button:disabled { cursor: wait; opacity: .55; }.secondary-button { border: 1px solid #d6deeb; background: #fff; color: #465a76; }.status-error, .status-notice { padding: 10px 13px; border-radius: 8px; font-size: 13px; margin: 0 0 16px; }.status-error { background: #fff0f1; color: #a83643; }.status-error button { border: 0; float: right; background: transparent; color: inherit; cursor: pointer; }.status-notice { background: #eaf7f0; color: #187450; }.status-metrics { display: grid; grid-template-columns: repeat(4, 1fr); gap: 13px; margin-bottom: 18px; }.status-metrics article { padding: 17px; background: #fff; border: 1px solid #e4e9f0; border-radius: 11px; }.status-metrics span, .status-metrics small { display: block; color: #77869b; font-size: 12px; }.status-metrics strong { display: block; font-size: 23px; margin: 5px 0; }.status-metrics .attention { border-color: #f0c9cc; background: #fffafa; }.status-grid { display: grid; grid-template-columns: 1.5fr 1fr; gap: 18px; margin-bottom: 18px; }.status-card { background: white; border: 1px solid #e3e9f1; border-radius: 12px; padding: 20px; box-shadow: 0 5px 17px rgba(19, 37, 65, .025); }.status-card-head { display: flex; ali